"""The SkyDiscover binding (design section 9): the generated config and
prompt templates, the model clients (an OpenAI-compatible endpoint, or
a CHIA model node dispatched to a worker with the credentials), the
seeds added to the backend's database, the run with its stop rules and
resume.

The generated `skydiscover.yaml` is a SkyDiscover config file: every key
is one SkyDiscover reads, so `skydiscover-run` accepts it unchanged.
ADIR's own search keys (operators, prompts, tactics, instructions,
budget, stop) stay in contract.json and act through the composer behind
the model client and the watcher of `run`."""
from __future__ import annotations

import re
import shutil
import asyncio
import json
import logging
import os
import random
import threading
import time
import uuid
from pathlib import Path
from typing import Optional

import yaml

from ..errors import BindError
from ..instance import Instance

SEARCH_TYPES = {"adaevolve": "adaevolve", "evox": "evox", "topk": "topk", "beam_search": "beam_search",
                "best_of_n": "best_of_n", "openevolve": "openevolve", "gepa": "gepa",
                "shinkaevolve": "shinkaevolve"}
ROLE_LISTS = {"solution": "models", "guide": "guide_models", "evaluator": "evaluator_models"}
SUFFIX = {"c": ".c", "cpp": ".cc", "systemverilog": ".sv", "verilog": ".v", "python": ".py",
          "chisel": ".scala", "scala": ".scala", "yosys_script": ".ys", "tcl": ".tcl", "rust": ".rs",
          "go": ".go"}
LANGUAGE = {"c": "c", "cpp": "cpp", "systemverilog": "systemverilog", "verilog": "verilog",
            "python": "python", "chisel": "scala", "scala": "scala", "yosys_script": "text",
            "tcl": "tcl", "rust": "rust", "go": "go"}
AGENT_NODES = {"claude": ("chia.models.claude", "ClaudeCodeLLM"),
               "codex": ("chia.models.codex", "CodexLLM"),
               "opencode": ("chia.models.opencode", "OpenCodeLLM")}

EVALUATOR_PY = '''"""ADIR evaluator entry, generated by `adir check`. The backend calls
evaluate(program_path); ADIR runs the derived graph and returns the
metrics and the artifacts."""
import sys
from pathlib import Path

RUN_DIR = Path(__file__).resolve().parent
for p in {sys_paths!r}:
    if p not in sys.path:
        sys.path.insert(0, p)


def evaluate(program_path):
    from adir.evaluate_entry import evaluate_for_backend
    return evaluate_for_backend(str(RUN_DIR), program_path)


if __name__ == "__main__":
    import json
    from adir.evaluate_entry import evaluate_program
    print(json.dumps(evaluate_program(str(RUN_DIR), sys.argv[1]), indent=1, default=str))
'''

# The backend-side user templates carry only what the composer parses
# back out of SkyDiscover's rendering: the current program's id and
# text, the inspiration programs' ids, the previous attempts, and a
# marker after which the backend's own sections (retry context,
# paradigm guidance, sibling context) follow. The composer writes the
# message the model sees.
DIFF_USER = ("<<ADIR:current>>\n{current_program}\n<<ADIR:inspirations>>\n{inspiration_programs}\n"
             "<<ADIR:attempts>>\n{previous_attempts}\n<<ADIR:end>>\n")
FULL_USER = DIFF_USER


# ------------------------------------------------------------ the config

def model_entry(m: dict) -> dict:
    """One SkyDiscover `LLMModelConfig` entry from a `search.models` role."""
    e = {"name": str(m["model"]), "weight": float(m.get("weight", 1.0))}
    if m.get("effort"):
        e["reasoning_effort"] = str(m["effort"])
    if m.get("timeout_s"):
        e["timeout"] = int(m["timeout_s"])
    return e


def config(inst: Instance, run: Path) -> dict:
    s = inst.search
    backend = inst.backend
    if backend not in SEARCH_TYPES:
        raise BindError("search.backend", f"{backend!r} has no SkyDiscover search type")
    seeds = inst.seed_artifacts()
    lang = seeds[0].language if seeds else "text"
    models = s.get("models") or {}
    llm = {"timeout": int(s.get("llm_timeout_s") or 1800), "retries": 3,
           "max_tokens": int(s.get("max_tokens") or 32000)}
    for role, key in ROLE_LISTS.items():
        if role in models:
            llm[key] = [model_entry(models[role])]
    others = [model_entry(m) for role, m in models.items() if role not in ROLE_LISTS]
    if others and "guide_models" not in llm:
        llm["guide_models"] = others
    n_seeds = len((s.get("seeds") or {}).get("generated") or []) + \
        len((s.get("seeds") or {}).get("files") or []) or 1
    db = {"db_path": str(run / "skydiscover" / "db")}
    if backend == "adaevolve":
        db.update({"num_islands": n_seeds, "max_islands": max(5, n_seeds),
                   "max_error_retries": (int(s["attempts"]) - 1 if s.get("attempts") else int(s.get("retries", 2)))})
        if inst.goal.kind == "pareto":
            db["pareto_objectives"] = [f"goal.{i + 1}" for i in range(len(inst.goal.levels))]
            db["higher_is_better"] = {f"goal.{i + 1}": d == "maximize"
                                      for i, (d, _) in enumerate(inst.goal.levels)}
            db["fitness_key"] = "combined_score"
    db.update(dict(s.get("database") or {}))
    cfg = {
        "max_iterations": int(s.get("iterations", 100)),
        "checkpoint_interval": int(s.get("checkpoint_interval") or 1),   # every iteration: a stopped run resumes where it stopped
        "random_seed": int(s.get("random_seed", 42)),   # one per repetition (adir run --seed overrides)
        "log_level": "INFO",
        "log_dir": str(run / "skydiscover" / "logs"),
        "language": LANGUAGE.get(lang, "text"),
        "file_suffix": SUFFIX.get(lang, ".txt"),
        "diff_based_generation": bool(s.get("diff_mode", True)),
        "max_solution_length": int(s.get("max_solution_bytes", 400000)),
        "llm": llm,
        "prompt": {"template": "evox" if backend == "evox" else "default",
                   "template_dir": str(run / "prompt_templates"),
                   "system_message": "problem.md",
                   "suggest_simplification_after_chars": None},
        "search": {"type": SEARCH_TYPES[backend],
                   "num_inspirations": int((s.get("context") or {}).get("programs", 1)),
                   "database": db},
        "evaluator": {"timeout": int(s.get("eval_timeout_s") or 3600), "max_retries": 0,
                      "cascade_evaluation": False,
                      "parallel_evaluations": int(s.get("parallel", 1))},
    }
    return cfg


def write(inst: Instance, run: Path, sys_paths: list) -> dict:
    run.mkdir(parents=True, exist_ok=True)
    cfg = config(inst, run)
    (run / "skydiscover.yaml").write_text(yaml.safe_dump(cfg, sort_keys=False))
    (run / "evaluator.py").write_text(EVALUATOR_PY.format(sys_paths=sys_paths))
    t = run / "prompt_templates"
    t.mkdir(exist_ok=True)
    (t / "diff_user.txt").write_text(DIFF_USER)
    (t / "full_rewrite_user.txt").write_text(FULL_USER)
    return cfg


# ------------------------------------------------------------ the clients

CLIENTS: dict = {}      # (run dir, role) -> the inner client, for calls ADIR makes itself


class AdirLLM:
    """The client SkyDiscover calls: the agent's client behind the
    composer, the sidecar and the call counter. For the solution role the composer writes the system and
    user messages from the instance and the archive; the backend's
    rendering is parsed for the parent and context ids only."""

    def __init__(self, inst: Instance, run: Path, spec: dict, role: str, inner, model_cfg):
        self.inst = inst
        self.run = Path(run)
        self.spec = spec
        self.role = role
        self.inner = inner
        self.name = getattr(model_cfg, "name", spec.get("model"))
        self.weight = getattr(model_cfg, "weight", 1.0)
        # the composer's draws: per unit and role, and per repetition seed and resume point when either is set
        # (a resumed run does not replay the draws its first leg made)
        salt = RUN_SALT.get(str(self.run))
        self.rng = random.Random(f"{inst.hashes.get('unit_id')}:{role}" + (f":{salt}" if salt else ""))
        self.lock = threading.Lock()
        CLIENTS[(str(self.run), role)] = inner

    def _ask(self, role: str, system: str, user: str) -> str:
        """A synchronous call to another model role (instruction
        proposals)."""
        inner = CLIENTS.get((str(self.run), role)) or make_inner(self.inst, self.run, role)
        CLIENTS[(str(self.run), role)] = inner
        out = asyncio.run(inner.generate(system, [{"role": "user", "content": user}]))
        _count(self.run, "llm_calls")
        _count(self.run, f"llm_calls.{role}")
        return out

    async def generate(self, system_message: str, messages: list, **kwargs) -> str:
        user = _user_text(messages)
        log_file = None
        sidecar = None
        parent_id = None
        logging_on = bool((self.inst.search.get("prompts") or {}).get("log", True))
        if self.role == "solution" and not self.inst.is_numeric:
            from ..composer import compose
            from ..prompts import write_sidecar
            loop = asyncio.get_event_loop()
            system_message, user, side = await loop.run_in_executor(
                None, lambda: compose(self.inst, self.run, user, self.rng, ask=self._ask,
                                      log=lambda m: print(f"[adir composer] {m}")))
            side["model"] = self.name
            parent_id = side.get("parent_id")
            sidecar = write_sidecar(self.run, side)
            log_file = Path(side["prompt_file"]) if side.get("prompt_file") else None
            kwargs["work_dir"] = side.get("workspace")
        else:
            from ..composer import call_workspace
            kwargs["work_dir"] = str(call_workspace(self.inst, self.run, self.role))
        if self.role == "solution":
            # one prompt, one submission, one evaluation by the harness: the same sentence in every method
            from ..confine import with_submission_note
            system_message = with_submission_note(system_message)
        if logging_on and log_file is None:
            # every other role's prompt (the backend's own request) is logged as sent
            d = self.run / "prompts"
            d.mkdir(exist_ok=True)
            log_file = d / f"{time.strftime('%Y%m%d-%H%M%S')}_{self.role}.md"
            log_file.write_text(f"<!-- role {self.role} -->\n\n# System\n\n{system_message}\n\n# User\n\n{user}\n")
        try:
            out = await self.inner.generate(system_message, [{"role": "user", "content": user}], **kwargs)
        except Exception as e:
            _count(self.run, "llm_failures")
            _count(self.run, f"llm_failures.{self.role}")
            if log_file is not None:
                with open(log_file, "a") as f:
                    f.write(f"\n\n# Reply\n\n(failed: {type(e).__name__}: {e})\n")
            if sidecar is not None:
                # no program comes of this call, so no evaluation takes its sidecar;
                # left pending, the next candidate could take it instead of its own
                sidecar.unlink(missing_ok=True)
            raise
        _count(self.run, "llm_calls")
        _count(self.run, f"llm_calls.{self.role}")
        if log_file is not None:
            with open(log_file, "a") as f:
                f.write(f"\n\n# Reply\n\n{out}\n")
        noted = []
        if self.role == "solution":
            try:
                noted = record_history(self.run, out, parent_id=parent_id)
            except Exception as e:      # noqa: BLE001 -- a lost note must not lose the candidate
                logging.getLogger(__name__).warning("history note not recorded: %s", e)
        if sidecar is not None:
            if not (out or "").strip():
                sidecar.unlink(missing_ok=True)
            else:
                from ..prompts import mark_answered
                # the entries this call left, so the evaluation of its candidate can retract
                # them where a `rollback` node reports the edit did not survive
                mark_answered(sidecar, history=noted)
        return out

    async def generate_image(self, *a, **k):
        raise NotImplementedError("ADIR models generate text")


def make_inner(inst: Instance, run: Path, role: str):
    """The inner client of a model role ADIR calls itself (a role
    SkyDiscover does not instantiate, such as `strategy`)."""
    specs = inst.search.get("models") or {}
    spec = specs.get(role)
    if spec is None:
        raise BindError("search.models", f"no model for the role {role!r}")
    return AgentLLM(spec, _agent_root(inst), run, role)


def _agent_root(inst: Instance) -> Path:
    from ..composer import agent_dir
    return agent_dir(inst)


def opencode_model(spec: dict) -> str:
    """opencode's `provider/model` id of a role: the spec's `provider` and
    `model` joined, or the `model` alone where it carries the provider
    already (`openrouter/z-ai/glm-5.3-flash`)."""
    model = str(spec["model"])
    provider = spec.get("provider")
    return f"{provider}/{model}" if provider and not model.startswith(f"{provider}/") else model


def opencode_small_model(spec: dict) -> str:
    """The model opencode uses for its own session-title and summary
    calls: the role's `small_model` (joined with the provider the same
    way), else the role's model, so no call leaves the named model."""
    small = spec.get("small_model")
    if not small:
        return opencode_model(spec)
    return opencode_model({**spec, "model": str(small)})


# opencode asks the provider for min(the model's own output limit, 32000) tokens unless
# OPENCODE_EXPERIMENTAL_OUTPUT_TOKEN_MAX raises the second term, and the limit counts reasoning.
# A reasoning model that thinks past it ends the step on `length` with no text: in one cacheflex
# run 71 of 127 DeepSeek calls came back empty that way, 31 of 36 guide calls among them. The
# default leaves the model's own limit in charge up to a quarter million tokens; far above that,
# opencode would reserve so much of the context for output that it compacts the session early.
OPENCODE_OUTPUT_TOKENS = 262144


def set_opencode_env(spec: dict) -> None:
    """Hand opencode the role's model and small model through
    OPENCODE_CONFIG_CONTENT, which opencode merges over its config
    files (the CHIA node passes its own file through OPENCODE_CONFIG
    and copies this process's environment), and the role's output
    token cap (`max_output_tokens`, else OPENCODE_OUTPUT_TOKENS). A run
    whose roles name one model sets it once; two roles with different
    models alternate it per call."""
    content = json.dumps({"model": opencode_model(spec), "small_model": opencode_small_model(spec)}, sort_keys=True)
    if os.environ.get("OPENCODE_CONFIG_CONTENT") != content:
        os.environ["OPENCODE_CONFIG_CONTENT"] = content
    os.environ["OPENCODE_EXPERIMENTAL_OUTPUT_TOKEN_MAX"] = str(
        int(spec.get("max_output_tokens") or OPENCODE_OUTPUT_TOKENS))


_HISTORY_RE = re.compile(
    r"<<<<<<<\s*HISTORY\s+(\S+)\s*\n(.*?)\n>>>>>>>\s*HISTORY", re.S)


def _known_regions(run) -> list:
    """The mutable regions the prompt of the newest solution call named,
    read from its sidecar. Empty where the sidecar predates the field, in
    which case a block's name is taken as written."""
    try:
        side = json.loads((Path(run) / "last_prompt.json").read_text())
    except Exception:  # noqa: BLE001 -- a missing sidecar only costs the check
        return []
    names = side.get("regions")
    return [str(n) for n in names] if isinstance(names, list) else []


def record_history(run, reply: str, parent_id: Optional[str] = None) -> list:
    """Append each HISTORY block of a reply to `<run>/history/<member>.md`.

    The agent is read-only in its call directory -- and must stay so,
    because the program that gets evaluated is the one rebuilt from the
    reply's SEARCH/REPLACE blocks, not the files on disk, so an agent that
    edited a file would believe it had changed something that never
    reaches an evaluation. The reply is therefore the only channel, and
    ADIR does the writing. That also attaches the entry to the call that
    produced it, which nothing else in the run does: a prompt file is
    named for the parent, and the candidate's id does not exist yet.

    Entries are appended oldest first so the prefix an agent re-reads each
    call stays byte-identical for the provider's cache. `effect:` is left
    for the composer to fill once the candidate has been measured.

    `parent_id` is the program the call edited: it goes into the entry's
    heading and into `history/lineage.json`, where the evaluation adds the
    candidate the entry produced, so a later call is shown only the entries
    on its own parent's ancestor chain (composer.lineage_history).
    """
    from ..composer import note_lineage
    written = []
    known = _known_regions(run)
    for member, body in _HISTORY_RE.findall(reply or ""):
        member = re.sub(r"[^\w.-]+", "_", member.strip())
        if not member:
            continue
        # the name is the region's, and the prompt names them. An agent that
        # labelled the block with a concept of its own would otherwise open a
        # history file per label, and the section that reads them back shows
        # the last entries of each file: the history of one region scattered
        # over several files is read back in pieces.
        if known and member not in known:
            if len(known) == 1:
                member = known[0]
            else:
                logging.getLogger(__name__).warning(
                    "history block named %r, which is no mutable region of the program (%s); "
                    "filed under _unattributed", member, ", ".join(known))
                member = "_unattributed"
        d = Path(run) / "history"
        d.mkdir(parents=True, exist_ok=True)
        f = d / f"{member}.md"
        n = len([1 for ln in f.read_text(errors="ignore").splitlines()
                 if ln.startswith("## ")]) if f.exists() else 0
        stamp = time.strftime('%Y-%m-%d %H:%M:%S') + (f"; parent {parent_id}" if parent_id else "")
        with open(f, "a") as fh:
            fh.write(f"\n## edit {n + 1} ({stamp})\n\n" + body.strip() + "\n")
        written.append({"region": member, "edit": n + 1})
    if written and parent_id:
        note_lineage(run, written, parent=str(parent_id))
    return written



class AgentLLM:
    """An agent CLI (claude, codex or opencode) as a SkyDiscover client,
    through its CHIA model node: each call builds the node with the
    system message and dispatches `prompt` through ray to the worker
    that holds `<agent>_creds` when a cluster is connected, else runs
    it in this process. The node's usage (tokens, and the cost where
    the CLI reports one) is counted into summary.json."""

    def __init__(self, spec: dict, agent_dir: Optional[Path], run: Optional[Path] = None, role: Optional[str] = None):
        self.spec = spec
        self.agent_dir = Path(agent_dir) if agent_dir else None
        self.run = Path(run) if run else None
        self.role = role
        self.agent = str(spec.get("agent"))
        if self.agent not in AGENT_NODES:
            raise BindError("search.models", f"agent {self.agent!r} is not one of {sorted(AGENT_NODES)}")

    def _cls(self):
        modname, clsname = AGENT_NODES[self.agent]
        try:
            import importlib
            return getattr(importlib.import_module(modname), clsname)
        except Exception as e:  # noqa: BLE001
            raise RuntimeError(f"the {self.agent} agent needs {modname}.{clsname} (CHIA): {e}") from None

    def _make(self, system_message: str, work_dir: Optional[str] = None):
        # the call's directory: what the prompts name, and the only tree the CLI is
        # pointed at (claude: --add-dir; codex and opencode: the working directory)
        s = self.spec
        root = work_dir or (str(self.agent_dir) if self.agent_dir else None)
        work_dir = s.get("work_dir") or root
        # a call is attempted `retries` times within `timeout_s` each (a provider stream that never completes is
        # the failure seen: ten steps in 16 minutes, then a stream idle until the timeout), so the default
        # allows one repeat rather than one long attempt
        kw = dict(model=opencode_model(s) if self.agent == "opencode" else str(s["model"]),
                  system_message=system_message, timeout_seconds=int(s.get("timeout_s") or 1200),
                  retries=max(1, int(s.get("retries", 2))))   # attempts of one call: 1 is a single attempt
        effort = s.get("effort")
        if self.agent == "claude":
            args = ["--bare", "--disallowedTools",
                    "Bash,Edit,Write,MultiEdit,NotebookEdit,WebFetch,WebSearch,Task,Agent"]
            if effort:
                args += ["--effort", str(effort)]
            if root:
                args += ["--add-dir", root]
            kw.update(extra_cli_args=args, dangerously_skip_permissions=False, log_stream=True)
        elif self.agent == "codex":
            kw.update(reasoning_effort=effort, dangerously_bypass_approvals_and_sandbox=False,
                      sandbox="read-only", work_dir=work_dir)
        else:
            # opencode keeps its file tools inside the call's directory; editing, the shell, the web and every
            # path outside the directory are denied, and a tool call repeated three times with the same input
            # fails at once (opencode's doom_loop guard defaults to a question nobody answers in a run).
            # The guard holds only outside a git repository: inside one, "outside the directory" means
            # outside the repository (adir.confine), so such a directory is refused here.
            from ..confine import assert_confinable
            assert_confinable(work_dir)
            kw.update(work_dir=work_dir, dangerously_skip_permissions=False,
                      config=opencode_permissions(),
                      extra_cli_args=(["--variant", str(effort)] if effort else []),
                      logging_level=logging.WARNING)
        return self._cls()(**kw)

    def _call(self, system_message: str, user: str, work_dir: Optional[str] = None) -> str:
        llm = self._make(system_message, work_dir)
        if self.agent == "opencode":
            set_opencode_env(self.spec)
        from ..nodes import CLUSTER, ray_get
        t0 = time.time()
        res, error = None, ""
        try:
            if CLUSTER["connected"]:
                res = ray_get(remote_prompt(llm).chia_remote(llm, user))
            else:
                res = llm.prompt(user)
        except Exception as e:  # noqa: BLE001 -- logged, then raised as before
            error = f"{type(e).__name__}: {e}"
            if is_billing_error(error) and self.run is not None:
                # the provider refuses every call from here on (no credit): every later iteration would
                # fail at once and still count, so the run stops (the Watcher reads the stop file) and a
                # resume after the account is topped up continues from the last real iteration
                try:
                    (self.run / "stop").write_text(f"billing: {error[:300]}\n")
                    (self.run / "stopped_by_billing").write_text(time.strftime("%Y-%m-%dT%H:%M:%S") + "\n")
                except OSError:
                    pass
            raise
        finally:
            self._log_call(res, time.time() - t0, work_dir, error, llm=llm, t0=t0)
        if not getattr(res, "success", False) or not getattr(res, "result", ""):
            raise RuntimeError(f"{self.agent} call failed (rc {getattr(res, 'returncode', '?')}): "
                               f"{(getattr(res, 'stderr', '') or '')[-800:]}")
        return res.result

    def _log_call(self, res, wall_s: float, work_dir, error: str = "", llm=None, t0: float = 0.0):
        """One line of `<run>/llm_calls.jsonl` per call, failed ones included: the role, the model, the wall
        time, the outcome, the usage the CLI reports (tokens, reasoning, cache, cost) and the call's directory,
        so every call of a run is accounted for beside the archive's candidates. The row is also kept as
        `last_call` for a caller without a run directory (a node such as chiALU's review)."""
        u = getattr(res, "usage", None) if res is not None else None
        if not isinstance(u, dict):
            u = {k: getattr(res, k, None) for k in ("input_tokens", "output_tokens", "cost_usd")} if res is not None else {}
        s = self.spec
        row = {"time": time.strftime("%Y-%m-%dT%H:%M:%S"), "role": self.role, "agent": self.agent,
               "provider": s.get("provider"), "model": s.get("model"), "effort": s.get("effort"),
               "max_output_tokens": s.get("max_output_tokens"), "wall_s": round(wall_s, 2),
               "success": bool(res is not None and getattr(res, "success", False) and getattr(res, "result", "")),
               "returncode": getattr(res, "returncode", None) if res is not None else None,
               "session_id": getattr(res, "session_id", None) if res is not None else None,
               "usage": {k: v for k, v in u.items() if v is not None}, "work_dir": str(work_dir) if work_dir else None,
               "error": error or ((getattr(res, "stderr", "") or "")[-800:] if res is not None and not getattr(res, "success", False) else "")}
        stream = str(getattr(res, "stream_result", "") or "") if res is not None else ""
        if self.agent == "opencode" and not row["session_id"] and work_dir and llm is not None:
            # an attempt the CLI did not return from (the timeout): its session is still in opencode's store,
            # so its tokens, cost and transcript are read back from there rather than lost
            rec = recover_opencode_session(llm, Path(work_dir), t0 or (time.time() - wall_s))
            if rec is not None:
                row["session_id"] = rec["session_id"]
                row["usage"] = {k: v for k, v in (rec["usage"] or {}).items() if v is not None} or row["usage"]
                row["recovered"] = True
                stream = rec["transcript"] or stream
        if stream and work_dir:
            # the agent's whole session (its reasoning, tool calls and file reads), beside the call's files;
            # calls that share a directory (the review's chunks) each keep their own
            try:
                d = Path(work_dir)
                f = d / "transcript.md"
                n = 2
                while f.exists():
                    f = d / f"transcript_{n}.md"
                    n += 1
                f.write_text(stream)
                row["transcript"] = str(f)
            except OSError:
                pass
        self.last_call = row
        self._count_usage_dict(row["usage"])
        if self.run is None:
            return
        try:
            self.run.mkdir(parents=True, exist_ok=True)
            with open(self.run / "llm_calls.jsonl", "a") as fh:
                fh.write(json.dumps(row, default=str) + "\n")
        except OSError:
            pass

    def _count_usage_dict(self, u: dict):
        """The run's token and cost counters, from every call's row, failed and recovered ones included."""
        if self.run is None:
            return
        for key in ("input_tokens", "output_tokens", "reasoning_tokens"):
            if u.get(key):
                _count(self.run, key, int(u[key]))
        if u.get("cost_usd"):
            _count(self.run, "cost_microusd", int(round(float(u["cost_usd"]) * 1e6)))

    async def generate(self, system_message: str, messages: list, **kwargs) -> str:
        loop = asyncio.get_event_loop()
        return await loop.run_in_executor(None, self._call, system_message, _user_text(messages),
                                          kwargs.get("work_dir"))


# opencode appends `external_directory allow <data dir>/opencode/tool-output/*` after the config's own rules
# (the last matching rule wins), so every agent could read that directory, which all runs share: truncated tool
# outputs of other calls and runs land there. It appends nothing where the config already denies exactly that
# glob, so the glob is denied as the last external_directory rule; and the file tools' own rules, which opencode
# checks beside external_directory and appends nothing to, deny the directory by pattern as well.
TOOL_OUTPUT_PATTERNS = ("*/opencode/tool-output", "*/opencode/tool-output/*")
FILE_TOOLS = ("read", "glob", "grep", "list")


def opencode_tool_output_globs(environ=None) -> list:
    """`<data>/opencode/tool-output/*` as opencode spells it ($XDG_DATA_HOME, else ~/.local/share), and
    the same through its real path where that differs."""
    env = os.environ if environ is None else environ
    data = env.get("XDG_DATA_HOME") or os.path.join(env.get("HOME") or os.path.expanduser("~"), ".local", "share")
    d = os.path.normpath(os.path.join(data, "opencode", "tool-output"))
    out = [os.path.join(d, "*")]
    real = os.path.join(os.path.realpath(d), "*")
    return out + ([real] if real not in out else [])


def opencode_permissions(environ=None) -> dict:
    """The permission block of every ADIR opencode call: editing, the shell, the web, subagents (extra,
    uncounted model calls) and every path outside the call's directory denied, opencode's shared tool-output
    directory included."""
    cfg = {"edit": "deny", "bash": "deny", "webfetch": "deny", "task": "deny",
           "external_directory": {"*": "deny", **{g: "deny" for g in opencode_tool_output_globs(environ)}},
           "doom_loop": "deny"}
    for tool in FILE_TOOLS:
        cfg[tool] = {"*": "allow", **{p: "deny" for p in TOOL_OUTPUT_PATTERNS}}
    return cfg


def remote_prompt(llm):
    """The handle `prompt` is dispatched through: ray's task retries off (`max_retries=0`), so a worker
    that dies mid-call fails the call instead of ray starting the whole agent session again unseen -- one
    iteration is one call, and each attempt's usage is the one row `_log_call` writes for it."""
    fn = llm.prompt
    opts = getattr(fn, "options", None)
    if callable(opts):
        try:
            return opts(max_retries=0, retry_exceptions=False)
        except TypeError:
            pass
    return fn


def _user_text(messages: list) -> str:
    parts = []
    for m in messages:
        c = m.get("content") if isinstance(m, dict) else m
        if isinstance(c, list):
            c = "\n".join(p.get("text", "") for p in c if isinstance(p, dict))
        if c:
            parts.append(str(c))
    return "\n\n".join(parts)


def _update_summary(run: Path, change):
    """Read, change and replace `<run>/summary.json` under a thread lock and a file lock: a review node in a
    worker process counts its calls into the same file, and a read of a half-written file used to come back
    as {} and wipe the run's counters."""
    import fcntl
    f = Path(run) / "summary.json"
    with _COUNT_LOCK, open(Path(run) / ".summary.lock", "a") as lk:
        fcntl.flock(lk, fcntl.LOCK_EX)
        try:
            try:
                d = json.loads(f.read_text()) if f.is_file() else {}
            except Exception:  # noqa: BLE001
                d = {}
            change(d)
            tmp = f.with_name(f".summary.{os.getpid()}.tmp")
            tmp.write_text(json.dumps(d, indent=1, default=str))
            os.replace(tmp, f)
        finally:
            fcntl.flock(lk, fcntl.LOCK_UN)


def _count(run: Path, key: str, n: int = 1):
    _update_summary(run, lambda d: d.__setitem__(key, int(d.get(key, 0)) + n))


_COUNT_LOCK = threading.Lock()


def install_clients(inst: Instance, cfg, run: Path, clients=None):
    """Set `init_client` on every model of the SkyDiscover config: the
    agent's client, or `clients(spec, role)` when given (tests)."""
    specs = inst.search.get("models") or {}
    root = _agent_root(inst)
    seen = set()
    for role, key in ROLE_LISTS.items():
        for mc in getattr(cfg.llm, key) or []:
            if id(mc) in seen:
                continue
            seen.add(id(mc))
            spec = specs.get(role) or next((m for m in specs.values() if str(m["model"]) == mc.name), None)
            if spec is None:
                continue
            spec_role = role if role in specs else next(r for r, m in specs.items() if m is spec)

            def factory(model_cfg, spec=spec, spec_role=spec_role):
                inner = clients(spec, spec_role) if clients is not None else AgentLLM(spec, root, run, spec_role)
                return AdirLLM(inst, run, spec, spec_role, inner, model_cfg)
            mc.init_client = factory


# ------------------------------------------------------------ the run

def seed_programs(run: Path) -> list:
    """[(name, program path, record)] of `adir seeds`."""
    from ..seeds import completed_seeds
    return [(name, prog, json.loads(rec.read_text()))
            for name, prog, rec in completed_seeds(run)]


def set_aside_database(cfg, out: Path) -> Optional[Path]:
    """Renames a database a previous run left at the config's `db_path` to
    `<name>.<stamp>` and returns the new path, or None when there was none.
    SkyDiscover's AdaEvolveDatabase loads whatever stands at `db_path` inside
    its base constructor, before its own attributes exist, and fails on
    `get_best_program`; a fresh run repopulates the database from the seeds
    and a resumed run from its checkpoint, so nothing is lost."""
    try:
        db_path = Path(getattr(cfg.search.database, "db_path", "") or out / "db")
    except AttributeError:
        db_path = out / "db"
    if not db_path.is_dir() or not any(db_path.iterdir()):
        return None
    moved = db_path.with_name(f"{db_path.name}.{time.strftime('%Y%m%d-%H%M%S')}")
    db_path.rename(moved)
    return moved


ARCHIVE_MARK = "adir_archive_lines.txt"
KEEP_CHECKPOINTS = 2                  # the newest two: the last one and the one before it, in case the last is cut short


def limit_attempts(attempts):
    """`search.attempts`: the candidates one iteration may try. SkyDiscover's default manager (best_of_n,
    beam_search, topk, ...) re-prompts up to `retry_times` = 3 times within an iteration when a reply does not
    parse or its candidate hard-fails, and the value is not in its config, so it is set on the call here;
    adaevolve takes `max_error_retries` = attempts - 1 (the database config above). Unset keeps SkyDiscover's
    behaviour. Returns the function that undoes the patch."""
    if not attempts:
        return lambda: None
    from skydiscover.search.default_discovery_manager import DiscoveryManager  # type: ignore
    orig = DiscoveryManager.run_discovery

    async def run_discovery(self, *a, **k):
        k["retry_times"] = int(attempts)
        return await orig(self, *a, **k)
    DiscoveryManager.run_discovery = run_discovery

    def restore():
        DiscoveryManager.run_discovery = orig
    return restore


_HTTP_402 = re.compile(r"(?:status|http|code|error|apierror)[^0-9a-z]{0,16}402\b|\b402\s+payment")


def is_billing_error(text: str) -> bool:
    """A provider's out-of-credit refusal (chia's BillingError; openrouter: 'exceed your available credits';
    DeepSeek: HTTP 402 'Insufficient Balance')."""
    t = (text or "").lower()
    return ("billingerror" in t or "billing_error" in t or "available credits" in t or "insufficient credit" in t
            or "insufficient balance" in t or "payment required" in t or bool(_HTTP_402.search(t)))


def recover_opencode_session(node, work_dir: Path, since_s: float) -> Optional[dict]:
    """The session opencode kept for a call whose CLI did not return: `opencode session list` names it by
    the call directory, `opencode export` gives its messages and the node's own parser the reply so far,
    the usage and the transcript (a3eval harness/plain_loop.py, where this was first written)."""
    import subprocess
    import tempfile
    binary = getattr(node, "opencode_bin", "opencode")
    wd = str(Path(work_dir).resolve())
    # opencode lists the sessions of the project its working directory belongs to, and a call directory
    # outside git is a project of its own: run from anywhere else, the list never names the call's session.
    # Both outputs go to files: opencode cuts piped output at 64 KiB, and a long list is cut mid-JSON.
    cwd = wd if Path(wd).is_dir() else None
    fd, lpath = tempfile.mkstemp(suffix=".json", prefix="adir_sessions_")
    os.close(fd)
    try:
        with open(lpath, "w") as fh:
            subprocess.run([binary, "session", "list", "--format", "json", "-n", "1000"], stdout=fh,
                           stderr=subprocess.DEVNULL, timeout=180, stdin=subprocess.DEVNULL, cwd=cwd)
        sessions = json.loads(Path(lpath).read_text() or "[]")
    except Exception:  # noqa: BLE001
        return None
    finally:
        try:
            os.unlink(lpath)
        except OSError:
            pass
    found = [x for x in sessions if isinstance(x, dict) and x.get("directory") == wd
             and (x.get("created") or 0) >= (since_s - 5) * 1000]
    if not found:
        return None
    sid = min(found, key=lambda x: x.get("created") or 0)["id"]     # the first session this call opened
    fd, path = tempfile.mkstemp(suffix=".json", prefix="adir_export_")
    os.close(fd)
    try:
        with open(path, "w") as fh:                  # a file: opencode cuts a piped export at 64 KiB
            subprocess.run([binary, "export", sid], stdout=fh, stderr=subprocess.DEVNULL, timeout=300,
                           stdin=subprocess.DEVNULL, cwd=cwd)
        export = json.loads(Path(path).read_text() or "{}")
        text, meta, stream, err = node._extract_from_export(export)
    except Exception:  # noqa: BLE001
        return None
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass
    return {"session_id": sid, "reply": text or "", "usage": dict(meta or {}), "transcript": stream or "", "error": err}


def track_checkpoints(controller, run_dir: Path, out: Path) -> list:
    """Every checkpoint the controller saves, in order, each with the archive's line count at that
    moment beside it (`<checkpoint>/adir_archive_lines.txt`): a resume trims the archive to it, so the
    candidates of an iteration no checkpoint covers are not kept twice."""
    saves: list = []
    orig = controller._save_checkpoint

    def save(iteration: int) -> None:
        orig(iteration)
        ev = getattr(getattr(controller, "discovery_manager", None), "shutdown_event", None)
        saves.append((int(iteration), bool(ev is not None and ev.is_set())))
        db = Path(run_dir) / "results_db.jsonl"
        n = sum(1 for l in db.read_text().splitlines() if l.strip()) if db.is_file() else 0
        d = Path(out) / "checkpoints" / f"checkpoint_{iteration}"
        try:
            (d / ARCHIVE_MARK).write_text(str(n))
        except OSError:
            pass
        # a checkpoint holds the whole database, so keeping one per iteration grows as the square of the
        # run; a resume reads the newest alone, so all but the newest KEEP_CHECKPOINTS go
        keep = int(os.environ.get("ADIR_KEEP_CHECKPOINTS", KEEP_CHECKPOINTS))
        cks = sorted((p for p in (Path(out) / "checkpoints").glob("checkpoint_*") if p.is_dir()),
                     key=lambda p: int(p.name.split("_")[-1]))
        for old in cks[:-keep] if keep > 0 else []:
            shutil.rmtree(old, ignore_errors=True)
    controller._save_checkpoint = save
    return saves


def drop_final_checkpoint(controller, out: Path, saves: list) -> None:
    """SkyDiscover saves a final checkpoint named after the last iteration it was *asked* to run, also
    when a stop (the signal handler, the `stop` file, a budget of the Watcher) ended the loop early; a
    resume would then count the unrun iterations as done. After an early stop that checkpoint goes
    unless an iteration's own checkpoint already carries its number."""
    if not saves:
        return
    final, stopping = saves[-1]           # the shutdown flag as it stood when the checkpoint was written
    if not stopping or final in [i for i, _ in saves[:-1]]:
        return
    shutil.rmtree(out / "checkpoints" / f"checkpoint_{final}", ignore_errors=True)
    print(f"[adir run] stopped early: removed the final checkpoint_{final}, which no iteration completed")


def trim_archive(run_dir: Path, ckpt: Optional[str]) -> None:
    """On resume: keep the archive lines the checkpoint covers (its ARCHIVE_MARK), or the seeds alone
    when there is no checkpoint (iteration 0 is never checkpointed), and set the evaluation counter back."""
    db = Path(run_dir) / "results_db.jsonl"
    if not db.is_file():
        return
    lines = [l for l in db.read_text().splitlines() if l.strip()]
    if ckpt is not None:
        mark = Path(ckpt) / ARCHIVE_MARK
        if not mark.is_file():
            return                                   # a checkpoint from before the mark: leave the archive as it is
        keep = lines[:int(mark.read_text())]
    else:
        keep = [l for l in lines if json.loads(l).get("is_seed")]
    if len(keep) == len(lines):
        return
    db.write_text("".join(l + "\n" for l in keep))
    its = [json.loads(l).get("iteration") for l in keep]
    (Path(run_dir) / "iteration.txt").write_text(str(max([i for i in its if isinstance(i, int)], default=0)))
    print(f"[adir run] resume: {len(lines) - len(keep)} archive record(s) past the checkpoint set aside")
    with open(Path(run_dir) / "results_db.trimmed.jsonl", "a") as f:
        f.write("".join(l + "\n" for l in lines[len(keep):]) if ckpt is not None else
                "".join(l + "\n" for l in lines if not json.loads(l).get("is_seed")))


def latest_checkpoint(out: Path) -> Optional[str]:
    d = out / "checkpoints"
    if not d.is_dir():
        return None
    cks = [p for p in d.glob("checkpoint_*") if p.is_dir()]
    if not cks:
        return None
    return str(max(cks, key=lambda p: int(p.name.split("_")[-1])))


class Watcher(threading.Thread):
    """Ends the run on the `stop` file, the wall and call budgets and the
    plateau rule (design section 9.6)."""

    def __init__(self, inst: Instance, run: Path, controller):
        super().__init__(daemon=True)
        self.inst = inst
        self.run_dir = Path(run)
        self.controller = controller
        self.t0 = time.time()
        self.stopped = threading.Event()
        self.reason = None

    def check(self) -> Optional[str]:
        s = self.inst.search
        budget = s.get("budget") or {}
        stop = s.get("stop") or {}
        if (self.run_dir / "stop").exists():
            return "stop file"
        wall = float(budget.get("wall_hours") or 0) * 3600
        if wall and time.time() - self.t0 > wall:
            return f"wall budget {budget['wall_hours']} h"
        f = self.run_dir / "summary.json"
        try:
            summary = json.loads(f.read_text()) if f.is_file() else {}
        except Exception:  # noqa: BLE001
            summary = {}
        calls = int(budget.get("llm_calls") or 0)
        if calls and int(summary.get("llm_calls", 0)) >= calls:
            return f"llm_calls budget {calls}"
        toks = int(budget.get("output_tokens") or 0)
        if toks and int(summary.get("output_tokens", 0)) >= toks:
            return f"output_tokens budget {toks}"
        recs = [r for r in self.inst.archive(self.run_dir).records() if not r.get("is_seed")]
        runs = int(budget.get("node_runs") or 0)
        if runs and sum(int((r.get("cost") or {}).get("node_calls") or 0) for r in recs) >= runs:
            return f"node_runs budget {runs}"
        plateau = int(stop.get("plateau_iterations") or 0)
        if plateau and len(recs) > plateau:
            best_before = max((r["score"]["combined_score"] for r in recs[:-plateau]), default=None)
            best_after = max(r["score"]["combined_score"] for r in recs[-plateau:])
            if best_before is not None and best_after <= best_before + 1e-12:
                return f"plateau of {plateau} iterations"
        return None

    def run(self):
        while not self.stopped.wait(5.0):
            try:
                reason = self.check()
            except Exception:  # noqa: BLE001
                reason = None
            if reason:
                self.reason = reason
                mgr = getattr(self.controller, "discovery_manager", None)
                if mgr is not None:
                    mgr.request_shutdown()
                _write_summary(self.run_dir, {"stopped_by": reason})
                return

    def stop(self):
        self.stopped.set()


def _write_summary(run: Path, update: dict):
    _update_summary(run, lambda d: d.update(update))


RUN_SALT: dict = {}     # run dir -> "seed:iterations done", the composer RNG's salt (AdirLLM)


def run(inst: Instance, run_dir: Path, resume: bool = False, iterations: Optional[int] = None,
        clients=None, seed: Optional[int] = None) -> dict:
    """The search through SkyDiscover's controller: the config from
    skydiscover.yaml, the clients installed, every seed of `adir seeds`
    in the database with its record's metrics, then the iterations."""
    try:
        from skydiscover.config import Config  # type: ignore
        from skydiscover.search.main_controller import MainController  # type: ignore
        from skydiscover.search.route import get_program  # type: ignore
    except ImportError:
        raise BindError("search.backend", f"backend {inst.backend} needs the skydiscover package; "
                                          f"the run directory {run_dir} holds skydiscover.yaml, "
                                          f"evaluator.py and seeds/ for a manual start") from None
    from ..evaluate import backend_result
    run_dir = Path(run_dir)
    seeds = seed_programs(run_dir)
    if not seeds:
        raise BindError("search.seeds", "run `adir seeds` first")
    cfg = Config.from_yaml(run_dir / "skydiscover.yaml")
    if iterations is not None:
        cfg.max_iterations = int(iterations)
    seed_file = run_dir / "search_seed.json"
    if seed is None and resume and seed_file.is_file():
        seed = json.loads(seed_file.read_text()).get("seed")   # a resumed repetition keeps its own seed
    if seed is not None:
        seed_file.write_text(json.dumps({"seed": int(seed)}))
    base_seed = int(seed) if seed is not None else int(cfg.random_seed if cfg.random_seed is not None else 42)
    out = run_dir / "skydiscover"
    out.mkdir(parents=True, exist_ok=True)
    ckpt = latest_checkpoint(out) if resume else None
    done = 0
    if ckpt is not None:
        import re as _re
        m = _re.search(r"(\d+)$", Path(ckpt).name)
        # ADIR puts the seeds in the database itself, so SkyDiscover counts from iteration 0 and
        # checkpoint_<k> holds iterations 0..k
        done = int(m.group(1)) + 1 if m else 0
    if resume:
        trim_archive(run_dir, ckpt)
    # the repetition's seed, moved on by the resume point: a resumed leg neither replays SkyDiscover's
    # draws (its controller reseeds `random` at start) nor the composer's
    eff_seed = base_seed if not done else (base_seed + 7919 * done) % (2 ** 31)
    cfg.random_seed = eff_seed
    if getattr(getattr(cfg, "search", None), "database", None) is not None:
        cfg.search.database.random_seed = eff_seed      # from_yaml copied the file's seed there already
    if seed is not None or done:
        RUN_SALT[str(run_dir)] = f"{base_seed}:{done}"
    install_clients(inst, cfg, run_dir, clients)
    if ckpt is not None:
        # `iterations` is the run's total: SkyDiscover runs that many more past its checkpoint, so a run
        # stopped at iteration k and resumed with the same total runs the remaining total - k, and a larger
        # total extends a finished run
        total = int(iterations) if iterations is not None else int(cfg.max_iterations)
        cfg.max_iterations = max(0, total - done)
        print(f"[adir run] resuming from {Path(ckpt).name}: {done} iterations done, {cfg.max_iterations} to the total of {total}")
    set_aside_database(cfg, out)
    controller = MainController(initial_program_path=str(seeds[0][1]),
                                evaluation_file=str(run_dir / "evaluator.py"),
                                config=cfg, output_dir=str(out))
    if ckpt is None:
        db = controller.database
        n_islands = int(getattr(db, "num_islands", 1) or 1)
        first = None
        for i, (name, path, rec) in enumerate(seeds):
            r = backend_result(inst, rec)
            prog = get_program(cfg, path.read_text(), str(uuid.uuid4()), r["metrics"], 0)
            try:
                prog.artifacts = r["artifacts"]
            except Exception:  # noqa: BLE001
                pass
            if hasattr(db, "num_islands"):
                db.add(prog, iteration=0, target_island=i % n_islands)
            else:
                db.add(prog, iteration=0)
            first = first or prog
        try:
            db.initial_program_id = first.id
            from skydiscover.utils.metrics_utils import get_fitness_score  # type: ignore
            db.initial_program_score = get_fitness_score(first.metrics or {})
        except Exception:  # noqa: BLE001
            pass
    _write_summary(run_dir, {"started": time.time(), "backend": inst.backend,
                             "iterations_requested": cfg.max_iterations, "resumed_from": ckpt})
    saves = track_checkpoints(controller, run_dir, out)
    restore = limit_attempts(inst.search.get("attempts"))
    watcher = Watcher(inst, run_dir, controller)
    watcher.start()
    try:
        best = asyncio.run(controller.run(iterations=cfg.max_iterations, checkpoint_path=ckpt))
    finally:
        watcher.stop()
        restore()
        drop_final_checkpoint(controller, out, saves)
    recs = inst.archive(run_dir).records()
    res = {"records": len(recs), "feasible": sum(1 for r in recs if r.get("feasible")),
           "best_score": (best.metrics or {}).get("combined_score") if best else None,
           "stopped_by": watcher.reason, "output_dir": str(out)}
    _write_summary(run_dir, {"finished": time.time(), **res})
    return res
